6	     5	public class ClaimOffice {
7	     6	
8	     7	    private static final BigDecimal PROCESSING_FEE = BigDecimal.valueOf(5);
9	     8	
10	     9	    private final Customer customer;
11	    10	    private final ContractHistory contractHistory = new ContractHistory();
12	    11	
13	    12	    public ClaimOffice(Customer customer) {
14	    13	        this.customer = customer;
15	    14	    }
16	    15	
17	    16	    /**
18	    17	     * The office quotes the premium for the items and, in doing so, writes the
19	    18	     * contract: the premium is priced against the customer's file as it stands, and
20	    19	     * only then does the new contract enter that file.
21	    20	     */
22	    21	    public int quote(List<Item> items) {
23	    22	        int premium = premiumFor(items);
24	    23	        contractHistory.recordContractWritten();
25	    24	        return premium;
26	    25	    }
27	    26	
28	    27	    /** The office writes a policy for the items, charging the quoted premium. */
29	    28	    public Policy insure(List<Item> items) {
30	    29	        return new Policy(items, quote(items));
31	    30	    }
32	    31	
33	    32	    /** The office settles a claim reported against one of its policies. */
34	    33	    public Settlement claim(Policy policy, Incident incident) {
35	    34	        return ClaimSettlement.forIncident(policy, incident);
36	    35	    }
37	    36	
38	    37	    /** What the office charges for these items: every scope's contribution, plus the fee. */
39	    38	    private int premiumFor(List<Item> items) {
40	    39	        BigDecimal premiumBeforeFee = PolicyModifiers.applyTo(
41	    40	                        PolicyBasePremium.of(items),
42	    41	                        customer.isLongStanding(),
43	    42	                        contractHistory.nextContractIsFollowUp())
44	    43	                .add(ItemRiskRating.surchargesFor(items));
45	    44	        return roundInOfficeFavour(premiumBeforeFee.add(PROCESSING_FEE));
46	    45	    }
47	    46	
48	    47	    /**
49	    48	     * A premium is rounded up: the MHPCO rounds in its own favour. Intermediate
50	    49	     * amounts stay exact fractions, so only this final step loses the remainder.
51	    50	     */
52	    51	    private static int roundInOfficeFavour(BigDecimal premium) {
53	    52	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
54	    53	    }
55	    54	}
