67	    11	/**
68	    12	 * The MHPCO's counter clerk: reads a scenario as JSON from stdin, has the office
69	    13	 * process its steps in order, and writes the results as JSON to stdout. Translation
70	    14	 * only -- every decision about premiums, payouts and what the office refuses to
71	    15	 * cover belongs to the office, not to the counter.
72	    16	 */
73	    17	public final class ClaimOfficeCli {
74	    18	
75	    19	    private static final ObjectMapper JSON = new ObjectMapper();
76	    20	
77	    21	    private ClaimOfficeCli() {
78	    22	    }
79	    23	
80	    24	    public static void main(String[] args) {
81	    25	        try {
82	    26	            String scenario = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
83	    27	            System.out.print(run(scenario));
84	    28	        } catch (RuntimeException | IOException rejected) {
85	    29	            PrintStream stderr = new PrintStream(System.err, true, StandardCharsets.UTF_8);
86	    30	            stderr.println(rejected.getMessage());
