88	    32	        }
89	    33	    }
90	    34	
91	    35	    /** Processes one scenario document and returns the result document. */
92	    36	    public static String run(String scenario) throws IOException {
93	    37	        JsonNode document = JSON.readTree(scenario);
94	    38	        ClaimOffice office = new ClaimOffice(customerOf(document.get("customer")));
95	    39	        List<Policy> policies = new ArrayList<>();
96	    40	
97	    41	        ArrayNode results = JSON.createArrayNode();
98	    42	        for (JsonNode step : document.get("steps")) {
99	    43	            results.add(resultOf(step, office, policies));
100	    44	        }
101	    45	
102	    46	        ObjectNode resultDocument = JSON.createObjectNode();
103	    47	        resultDocument.set("results", results);
104	    48	        return JSON.writeValueAsString(resultDocument);
105	    49	    }
106	    50	
107	    51	    /**
108	    52	     * What the office reports for one step. A quote leaves behind the policy it
109	    53	     * wrote, so a later claim can name it by the step that created it.
110	    54	     */
111	    55	    private static ObjectNode resultOf(JsonNode step, ClaimOffice office, List<Policy> policies) {
112	    56	        ObjectNode result = JSON.createObjectNode();
113	    57	        if ("quote".equals(step.get("op").asText())) {
114	    58	            Policy policy = office.insure(itemsOf(step.get("items")));
115	    59	            policies.add(policy);
116	    60	            result.put("premium", policy.premium());
117	    61	            return result;
118	    62	        }
119	    63	        policies.add(null);
120	    64	        Settlement settlement = office.claim(
121	    65	                policyNamedBy(step, policies), incidentOf(step.get("incident")));
122	    66	        result.put("payout", settlement.payout());
123	    67	        result.put("remainingCap", settlement.remainingCap());
124	    68	        return result;
125	    69	    }
126	    70	
127	    71	    /** The policy a claim step names by the zero-based index of its quote step. */
128	    72	    private static Policy policyNamedBy(JsonNode step, List<Policy> policies) {
129	    73	        int quoteStep = step.get("policy").asInt();
130	    74	        Policy policy = policies.get(quoteStep);
131	    75	        if (policy == null) {
132	    76	            throw new IllegalArgumentException("step " + quoteStep + " wrote no policy");
133	    77	        }
134	    78	        return policy;
135	    79	    }
136	    80	
137	    81	    private static Customer customerOf(JsonNode customer) {
138	    82	        return new Customer(customer.get("yearsWithMHPCO").asInt());
139	    83	    }
