141	    85	    private static List<Item> itemsOf(JsonNode items) {
142	    86	        List<Item> insured = new ArrayList<>();
143	    87	        for (JsonNode item : items) {
144	    88	            insured.add(new Item(
145	    89	                    item.get("type").asText(),
