147	    91	                    item.path("enchantment").asInt(),
148	    92	                    item.path("cursed").asBoolean()));
149	    93	        }
150	    94	        return insured;
151	    95	    }
152	    96	
153	    97	    private static Incident incidentOf(JsonNode incident) {
154	    98	        List<Damage> damages = new ArrayList<>();
155	    99	        for (JsonNode damage : incident.get("damages")) {
156	   100	            damages.add(new Damage(
157	   101	                    damage.get("itemType").asText(), damage.get("amount").asInt()));
158	   102	        }
159	   103	        return new Incident(incident.get("cause").asText(), damages);
160	   104	    }
