163	     1	import java.math.BigDecimal;
164	     2	import java.math.RoundingMode;
165	     3	import java.util.List;
166	     4	
167	     5	/**
168	     6	 * How the MHPCO settles damage reported against a policy: it resolves each reported
169	     7	 * damage to the insured item it names, asks its reimbursement clauses how much of
170	     8	 * that damage it recognises, withholds the deductible per damage event, and pays out
171	     9	 * the total.
172	    10	 *
173	    11	 * <p>Separate from what the office charges: a premium is priced from the price list,
174	    12	 * the customer's file and the item's risk, while a payout is decided from the damage
175	    13	 * and the damaged item alone. The two change for different reasons -- so much so that
176	    14	 * the office's own favour points in opposite directions, rounding a premium up but a
177	    15	 * payout down.
178	    16	 */
179	    17	public final class ClaimSettlement {
180	    18	
181	    19	    /** The MHPCO keeps this much of every damage event to itself. */
182	    20	    private static final BigDecimal DEDUCTIBLE_PER_DAMAGE = BigDecimal.valueOf(100);
183	    21	
184	    22	    private ClaimSettlement() {
185	    23	    }
186	    24	
187	    25	    /** What the office pays out for everything the incident damaged. */
188	    26	    public static Settlement forIncident(Policy policy, Incident incident) {
189	    27	        BigDecimal payout = BigDecimal.ZERO;
190	    28	        for (DamagedItem damagedItem : policy.damagedItemsFor(incident.damages())) {
191	    29	            payout = payout.add(reimbursementFor(damagedItem));
192	    30	        }
193	    31	        int paid = policy.drawAgainstCap(roundInOfficeFavour(payout));
194	    32	        return new Settlement(paid, policy.remainingCap());
195	    33	    }
196	    34	
197	    35	    /** What the office reimburses for one damaged item, after its deductible. */
198	    36	    private static BigDecimal reimbursementFor(DamagedItem damagedItem) {
199	    37	        return ReimbursementClause
200	    38	                .recognisedAmountOf(damagedItem.damage(), damagedItem.item())
201	    39	                .subtract(DEDUCTIBLE_PER_DAMAGE);
202	    40	    }
203	    41	
204	    42	    /**
205	    43	     * A payout is rounded down: the MHPCO rounds in its own favour. Intermediate
206	    44	     * amounts stay exact fractions, so only this final step loses the remainder.
207	    45	     */
208	    46	    private static int roundInOfficeFavour(BigDecimal payout) {
209	    47	        return payout.setScale(0, RoundingMode.FLOOR).intValueExact();
210	    48	    }
211	    49	}
