293	    10	
294	    11	    private static final BigDecimal CURSE_SURCHARGE_RATE = Modifier.rate(50);
295	    12	    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = Modifier.rate(30);
296	    13	
297	    14	    /** From this enchantment level on, the MHPCO considers an item highly enchanted. */
298	    15	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
299	    16	
300	    17	    private ItemRiskRating() {
301	    18	    }
302	    19	
303	    20	    /** The risk surcharges every item in the policy contributes, added up. */
304	    21	    public static BigDecimal surchargesFor(List<Item> items) {
305	    22	        return items.stream()
306	    23	                .map(ItemRiskRating::surchargeFor)
307	    24	                .reduce(BigDecimal.ZERO, BigDecimal::add);
308	    25	    }
309	    26	
310	    27	    /** What this item's own risky traits add to the premium. */
311	    28	    private static BigDecimal surchargeFor(Item item) {
312	    29	        BigDecimal itemBasePremium = MhpcoPriceList.basePremiumOf(item);
313	    30	        BigDecimal surcharge = BigDecimal.ZERO;
314	    31	        if (item.cursed()) {
315	    32	            surcharge = surcharge.add(itemBasePremium.multiply(CURSE_SURCHARGE_RATE));
316	    33	        }
317	    34	        if (isHighlyEnchanted(item)) {
318	    35	            surcharge = surcharge.add(
319	    36	                    itemBasePremium.multiply(HIGH_ENCHANTMENT_SURCHARGE_RATE));
320	    37	        }
321	    38	        return surcharge;
322	    39	    }
323	    40	
324	    41	    private static boolean isHighlyEnchanted(Item item) {
325	    42	        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
326	    43	    }
