328	===== MhpcoPriceList.java =====
329	     1	import java.math.BigDecimal;
330	     2	import java.util.Map;
331	     3	import java.util.Set;
332	     4	
333	     5	/**
334	     6	 * The MHPCO price list: what the office charges as a base premium for each item type
335	     7	 * it covers, and what it insures that type for, before any modifier that depends on
336	     8	 * the item, the customer or the contract. A lookup only -- the offers the office makes
337	     9	 * on top of these prices, such as the component building block, live with the pricing
338	    10	 * that grants them.
339	    11	 *
340	    12	 * <p>The list is also the office's roster of insurable types, and deliberately so: a
341	    13	 * type the list does not name has neither a premium nor an insurance value, so there
342	    14	 * is no state in which the office could price a type it does not cover, or cover a
343	    15	 * type it cannot price. Naming a type and pricing it are one entry, revised in one
344	    16	 * edit.
345	    17	 */
346	    18	public final class MhpcoPriceList {
347	    19	
348	    20	    /**
349	    21	     * One row of the price list: the two figures the list states side by side for an
350	    22	     * item type. They are quoted together and revised together, so the list records
351	    23	     * them together.
352	    24	     */
353	    25	    private record Entry(int basePremium, int insuranceValue) {
354	    26	    }
355	    27	
356	    28	    /** The main item types the office covers, each with its row of the price list. */
357	    29	    private static final Map<String, Entry> MAIN_ITEMS = Map.of(
358	    30	            "sword", new Entry(100, 1000),
359	    31	            "amulet", new Entry(60, 600),
360	    32	            "staff", new Entry(80, 800),
361	    33	            "potion", new Entry(40, 400));
362	    34	
363	    35	    /**
364	    36	     * Components are a family of small item types the MHPCO prices alike, so the list
365	    37	     * states one row for the whole family rather than repeating it per type.
366	    38	     */
367	    39	    private static final Entry COMPONENT_ENTRY = new Entry(25, 250);
368	    40	
369	    41	    /** The component types the office covers. All are priced at {@link #COMPONENT_ENTRY}. */
370	    42	    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");
371	    43	
372	    44	    static final int COMPONENT_BASE_PREMIUM = COMPONENT_ENTRY.basePremium();
373	    45	
374	    46	    private MhpcoPriceList() {
375	    47	    }
376	    48	
377	    49	    /**
378	    50	     * What a single item costs on its own, ignoring any building block it belongs to.
379	    51	     * Item risk surcharges are shares of this amount.
380	    52	     */
381	    53	    public static BigDecimal basePremiumOf(Item item) {
382	    54	        return BigDecimal.valueOf(entryFor(item).basePremium());
383	    55	    }
384	    56	
385	    57	    /**
386	    58	     * What the office insures a single item for. Unlike the base premium, this is
387	    59	     * never reduced by an offer: a building block is cheaper to insure, not worth less.
388	    60	     */
389	    61	    public static int insuranceValueOf(Item item) {
