431	===== Policy.java =====
432	     1	import java.util.ArrayList;
433	     2	import java.util.List;
434	     3	
435	     4	/**
436	     5	 * A contract the MHPCO has written: the items it covers, the premium charged, and
437	     6	 * how much of its payout cap is still available.
438	     7	 */
439	     8	public final class Policy {
440	     9	
441	    10	    /** The office never pays out more than this multiple of the insurance sum. */
442	    11	    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
443	    12	
444	    13	    private final List<Item> items;
445	    14	    private final int premium;
446	    15	    private int remainingCap;
447	    16	
448	    17	    public Policy(List<Item> items, int premium) {
449	    18	        this.items = List.copyOf(items);
450	    19	        this.premium = premium;
451	    20	        this.remainingCap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum();
452	    21	    }
453	    22	
454	    23	    /**
455	    24	     * The insured items the damages of one incident struck, each paired with its damage,
456	    25	     * in the order reported. Each
457	    26	     * damage claims a covered item of its own: a policy covering two swords can suffer
458	    27	     * two sword damages, but a claim naming more items of a type than the policy
459	    28	     * covers -- or a type it does not cover at all -- is not a claim on this policy.
460	    29	     *
461	    30	     * <p>What the policy covers is the policy's own knowledge, so the policy answers
462	    31	     * the question rather than handing out its items.
463	    32	     */
464	    33	    List<DamagedItem> damagedItemsFor(List<Damage> damages) {
465	    34	        List<Item> stillUnclaimed = new ArrayList<>(items);
466	    35	        List<DamagedItem> damagedItems = new ArrayList<>();
467	    36	        for (Damage damage : damages) {
468	    37	            damagedItems.add(new DamagedItem(damage, claimOne(stillUnclaimed, damage)));
469	    38	        }
470	    39	        return List.copyOf(damagedItems);
471	    40	    }
472	    41	
473	    42	    /** Takes one covered item of the damaged type out of those not yet claimed. */
474	    43	    private static Item claimOne(List<Item> stillUnclaimed, Damage damage) {
475	    44	        for (int i = 0; i < stillUnclaimed.size(); i++) {
476	    45	            if (stillUnclaimed.get(i).type().equals(damage.itemType())) {
477	    46	                return stillUnclaimed.remove(i);
478	    47	            }
479	    48	        }
480	    49	        throw new IllegalArgumentException(
481	    50	                "the policy does not cover a further item of type: " + damage.itemType());
482	    51	    }
483	    52	
484	    53	    public int premium() {
485	    54	        return premium;
486	    55	    }
487	    56	
488	    57	    /** What remains of the total the office will pay out over this policy's life. */
489	    58	    public int remainingCap() {
490	    59	        return remainingCap;
491	    60	    }
492	    61	
493	    62	    /**
494	    63	     * The office draws a settled payout against the policy's cap and pays out what
495	    64	     * the cap still allows: a desired payout beyond the remaining cap is reduced to
496	    65	     * it. The cap is the policy's own ledger -- only the policy knows how much of it
497	    66	     * earlier claims have already spent.
498	    67	     */
499	    68	    int drawAgainstCap(int desiredPayout) {
500	    69	        int paid = Math.min(desiredPayout, remainingCap);
501	    70	        remainingCap -= paid;
502	    71	        return paid;
503	    72	    }
504	    73	
505	    74	    /** What the policy insures in total: the sum of its items' insurance values. */
506	    75	    private int insuranceSum() {
507	    76	        return items.stream().mapToInt(MhpcoPriceList::insuranceValueOf).sum();
