512	     2	import java.util.List;
513	     3	import java.util.Map;
514	     4	import java.util.stream.Collectors;
515	     5	
516	     6	/**
517	     7	 * What the office charges for a policy's items before any modifier: every main item
518	     8	 * at its price-list premium, and each group of alike components priced together, so
519	     9	 * that the MHPCO's building-block offer can be recognised.
520	    10	 *
521	    11	 * <p>The block is an offer on the premium alone. It deliberately says nothing about
522	    12	 * what the office insures those components for.
523	    13	 */
524	    14	public final class PolicyBasePremium {
525	    15	
526	    16	    /** A building block of exactly 3 alike components is offered at a special price. */
527	    17	    private static final int COMPONENT_BLOCK_SIZE = 3;
528	    18	    private static final int COMPONENT_BLOCK_BASE_PREMIUM = 60;
529	    19	
530	    20	    private PolicyBasePremium() {
531	    21	    }
532	    22	
533	    23	    public static BigDecimal of(List<Item> items) {
534	    24	        BigDecimal mainItems = items.stream()
535	    25	                .filter(item -> !MhpcoPriceList.isComponent(item))
536	    26	                .map(MhpcoPriceList::basePremiumOf)
537	    27	                .reduce(BigDecimal.ZERO, BigDecimal::add);
538	    28	        BigDecimal components = alikeComponentCounts(items).values().stream()
539	    29	                .map(PolicyBasePremium::alikeComponentsBasePremiumOf)
540	    30	                .reduce(BigDecimal.ZERO, BigDecimal::add);
541	    31	        return mainItems.add(components);
542	    32	    }
543	    33	
544	    34	    /** How many components of each type the policy covers, grouped by their type. */
545	    35	    private static Map<String, Long> alikeComponentCounts(List<Item> items) {
546	    36	        return items.stream()
547	    37	                .filter(MhpcoPriceList::isComponent)
548	    38	                .collect(Collectors.groupingBy(Item::type, Collectors.counting()));
549	    39	    }
550	    40	
551	    41	    /**
552	    42	     * What the office charges for the alike components of one type: a building block
553	    43	     * is offered at its special price, anything else is priced component by component.
554	    44	     */
555	    45	    private static BigDecimal alikeComponentsBasePremiumOf(long alikeCount) {
556	    46	        if (formsBuildingBlock(alikeCount)) {
557	    47	            return BigDecimal.valueOf(COMPONENT_BLOCK_BASE_PREMIUM);
558	    48	        }
559	    49	        return BigDecimal.valueOf(alikeCount * MhpcoPriceList.COMPONENT_BASE_PREMIUM);
560	    50	    }
561	    51	
562	    52	    /** The block price is offered for exactly 3 alike components -- no more, no less. */
563	    53	    private static boolean formsBuildingBlock(long alikeCount) {
564	    54	        return alikeCount == COMPONENT_BLOCK_SIZE;
565	    55	    }
566	    56	}
567	===== PolicyModifiers.java =====
568	     1	import java.math.BigDecimal;
569	     2	
570	     3	/**
571	     4	 * The modifiers the MHPCO applies to a policy as a whole, as opposed to the risk it
572	     5	 * rates on an individual item. Each is a share of the policy base premium: the office
573	     6	 * charges for taking on a contract, not for the particular items in it.
574	     7	 *
575	     8	 * <p>The office knows three, and they stack additively on the same base:
576	     9	 *
577	    10	 * <ul>
578	    11	 *   <li>a 10 % initial assessment surcharge, levied on every quote -- each item in a
579	    12	 *       quote is a first insurance, whatever the customer's history;</li>
580	    13	 *   <li>a 20 % loyalty discount for a long-standing customer;</li>
581	    14	 *   <li>a 15 % discount on every contract after the customer's first.</li>
582	    15	 * </ul>
583	    16	 *
584	    17	 * <p>Separate from {@link ItemRiskRating}: these change when the office revises the
585	    18	 * terms it offers a customer, while an item surcharge changes when the office revises
586	    19	 * the risk it sees in an item. The processing fee is neither -- it is a flat charge
587	    20	 * added after every modifier, so it stays with the office's final reckoning.
588	    21	 */
589	    22	public final class PolicyModifiers {
590	    23	
591	    24	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = Modifier.rate(10);
592	    25	    private static final BigDecimal LOYALTY_DISCOUNT_RATE = Modifier.rate(20);
593	    26	    private static final BigDecimal FOLLOW_UP_CONTRACT_DISCOUNT_RATE = Modifier.rate(15);
594	    27	
595	    28	    private PolicyModifiers() {
596	    29	    }
597	    30	
598	    31	    /**
599	    32	     * The policy base premium adjusted by every policy-wide modifier that applies to
600	    33	     * this contract.
601	    34	     */
602	    35	    public static BigDecimal applyTo(
603	    36	            BigDecimal policyBasePremium, boolean longStandingCustomer, boolean followUpContract) {
604	    37	        BigDecimal adjusted = policyBasePremium
605	    38	                .add(policyBasePremium.multiply(FIRST_INSURANCE_SURCHARGE_RATE));
606	    39	        if (longStandingCustomer) {
607	    40	            adjusted = adjusted.subtract(policyBasePremium.multiply(LOYALTY_DISCOUNT_RATE));
608	    41	        }
609	    42	        if (followUpContract) {
610	    43	            adjusted = adjusted.subtract(
611	    44	                    policyBasePremium.multiply(FOLLOW_UP_CONTRACT_DISCOUNT_RATE));
612	    45	        }
613	    46	        return adjusted;
614	    47	    }
615	    48	}
616	===== ReimbursementClause.java =====
617	     1	import java.math.BigDecimal;
618	     2	
619	     3	/**
620	     4	 * The MHPCO's clauses on how much of a reported damage it recognises at all, before
621	     5	 * the deductible is withheld. A clause looks only at the damaged item and the amount
622	     6	 * claimed: it is the office's statement about the risk the item carried, not about
623	     7	 * the customer, the contract or the price list.
624	     8	 *
625	     9	 * <p>The office knows two clauses, and reads them in this order of precedence:
626	    10	 *
627	    11	 * <ol>
628	    12	 *   <li>Damage to a highly enchanted item (enchantment level &gt;= 8) is recognised
629	    13	 *       at half. This clause wins wherever it applies.</li>
630	    14	 *   <li>Damage to an item of dragon material is recognised in full.</li>
631	    15	 * </ol>
632	    16	 *
633	    17	 * <p>Only the first clause is encoded below, and deliberately so. Full recognition is
634	    18	 * already the office's default for every damage no clause touches, so the dragon-material
635	    19	 * clause prescribes exactly what would happen without it: it is stated by the tariff but
636	    20	 * changes no amount. Encoding it would mean a branch returning the same figure as the
637	    21	 * fall-through, which no claim could ever tell apart -- the office would be unable to
638	    22	 * check the clause it had written down. The clause is therefore recorded here rather
639	    23	 * than in code, and {@link Item#material()} accordingly bears on no payout today. Should
640	    24	 * the office ever lower its default recognition below full, this clause becomes
641	    25	 * observable and earns its branch, immediately above the default.
642	    26	 *
643	    27	 * <p>The recognised amount stays an exact fraction -- a halved damage of an odd amount is
644	    28	 * genuinely a half-G, and the MHPCO's rounding belongs to the final payout alone.
645	    29	 */
646	    30	public final class ReimbursementClause {
647	    31	
648	    32	    /** From this enchantment level on, the office recognises only half a damage. */
649	    33	    private static final int HALVED_REIMBURSEMENT_ENCHANTMENT = 8;
650	    34	
651	    35	    private static final BigDecimal HALF = BigDecimal.valueOf(5, 1);
652	    36	
653	    37	    private ReimbursementClause() {
654	    38	    }
655	    39	
656	    40	    /** How much of this damage to this item the office recognises. */
657	    41	    public static BigDecimal recognisedAmountOf(Damage damage, Item item) {
658	    42	        BigDecimal claimed = BigDecimal.valueOf(damage.amount());
659	    43	        if (isHighlyEnchanted(item)) {
660	    44	            return claimed.multiply(HALF);
661	    45	        }
662	    46	        return claimed;
663	    47	    }
664	    48	
665	    49	    /** Whether the halving clause reaches this item at all. */
666	    50	    private static boolean isHighlyEnchanted(Item item) {
667	    51	        return item.enchantment() >= HALVED_REIMBURSEMENT_ENCHANTMENT;
668	    52	    }
669	    53	}
